static inline bool lock_impl_trylock(struct lock_impl *lock) /* <=== lock_impl_trylock */ 
{
#ifdef RUN
	/* TODO: Should this be a test and set? */
	return __sync_bool_compare_and_swap(&lock->locked, false, true);
#else
	__CPROVER_atomic_begin();
	bool old_locked = lock->locked;
	lock->locked = true;
	__CPROVER_atomic_end();

	/* Minimal barrier to prevent accesses leaking out of lock. */
	__CPROVER_fence("RRfence", "RWfence");

	return !old_locked;
#endif
}

static inline int netlink_is_kernel(struct sock *sk) /* <=== netlink_is_kernel */ 
{
	return nlk_sk(sk)->flags & NETLINK_F_KERNEL_SOCKET;
}

static int __netlink_sendskb(struct sock *sk, struct sk_buff *skb) /* <=== __netlink_sendskb */ 
{
	int len = skb->len;

	netlink_deliver_tap(skb);

	skb_queue_tail(&sk->sk_receive_queue, skb);
	sk->sk_data_ready(sk);
	return len;
}

