static inline void sk_mem_charge(struct sock *sk, int size) /* <=== sk_mem_charge */ 
{
	if (!sk_has_account(sk))
		return;
	sk->sk_forward_alloc -= size;
}

static inline int test_tsk_thread_flag(struct task_struct *tsk, int flag) /* <=== test_tsk_thread_flag */ 
