	assert(!ret);
}

static inline void lock_impl_lock(struct lock_impl *lock) /* <=== lock_impl_lock */ 
{
	/*
	 * CBMC doesn't support busy waiting, so just assume that the
	 * lock is available.
	 */
	assume(lock_impl_trylock(lock));

	/*
	 * If the lock was already held by this thread then the assumption
	 * is unsatisfiable (deadlock).
	 */
}

static void netlink_overrun(struct sock *sk) /* <=== netlink_overrun */ 
{
	struct netlink_sock *nlk = nlk_sk(sk);

	if (!(nlk->flags & NETLINK_F_RECV_NO_ENOBUFS)) {
		if (!test_and_set_bit(NETLINK_S_CONGESTED,
				      &nlk_sk(sk)->state)) {
			sk->sk_err = ENOBUFS;
			sk->sk_error_report(sk);
		}
	}
	atomic_inc(&sk->sk_drops);
}

static inline void put_user_ns(struct user_namespace *ns) /* <=== put_user_ns */ 
{
}

int netlink_sendskb(struct sock *sk, struct sk_buff *skb) /* <=== netlink_sendskb */ 
{
	int len = __netlink_sendskb(sk, skb);

	sock_put(sk);
	return len;
}

static inline void spin_lock(spinlock_t *lock) /* <=== spin_lock */ 
{
	/*
	 * Spin locks also need to be removed in order to eliminate all
	 * memory barriers. They are only used by the write side anyway.
	 */
#ifndef NO_SYNC_SMP_MB
	preempt_disable();
	lock_impl_lock(&lock->internal_lock);
#endif
}

void kfree_skb(struct sk_buff *skb) /* <=== kfree_skb */ 
{
	if (!skb_unref(skb))
		return;

	trace_kfree_skb(skb, __builtin_return_address(0));
	__kfree_skb(skb);
}

static inline void spin_unlock(spinlock_t *lock) /* <=== spin_unlock */ 
{
#ifndef NO_SYNC_SMP_MB
	lock_impl_unlock(&lock->internal_lock);
	preempt_enable();
#endif
}

static inline int sock_intr_errno(long timeo) /* <=== sock_intr_errno */ 
{
	return timeo == MAX_SCHEDULE_TIMEOUT ? -ERESTARTSYS : -EINTR;
}

static inline struct socket *SOCKET_I(struct inode *inode) /* <=== SOCKET_I */ 
{
	return &container_of(inode, struct socket_alloc, vfs_inode)->socket;
}

static void netlink_skb_set_owner_r(struct sk_buff *skb, struct sock *sk) /* <=== netlink_skb_set_owner_r */ 
{
	WARN_ON(skb->sk != NULL);
	skb->sk = sk;
	skb->destructor = netlink_skb_destructor;
	atomic_add(skb->truesize, &sk->sk_rmem_alloc);
	sk_mem_charge(sk, skb->truesize);
}

static void remove_notification(struct mqueue_inode_info *info) /* <=== remove_notification */ 
{
	if (info->notify_owner != NULL &&
	    info->notify.sigev_notify == SIGEV_THREAD) {
		set_cookie(info->notify_cookie, NOTIFY_REMOVED);
		netlink_sendskb(info->notify_sock, info->notify_cookie);
	}
	put_pid(info->notify_owner);
	put_user_ns(info->notify_user_ns);
	info->notify_owner = NULL;
	info->notify_user_ns = NULL;
}

struct sock *netlink_getsockbyfilp(struct file *filp) /* <=== netlink_getsockbyfilp */ 
{
	struct inode *inode = file_inode(filp);
	struct sock *sock;

	if (!S_ISSOCK(inode->i_mode))
		return ERR_PTR(-ENOTSOCK);

	sock = SOCKET_I(inode)->sk;
	if (sock->sk_family != AF_NETLINK)
		return ERR_PTR(-EINVAL);

	sock_hold(sock);
	return sock;
}

static inline void lock_impl_unlock(struct lock_impl *lock) /* <=== lock_impl_unlock */ 
{
#ifdef RUN
	BUG_ON(!__sync_bool_compare_and_swap(&lock->locked, true, false));
#else
	/* Minimal barrier to prevent accesses leaking out of lock. */
	__CPROVER_fence("RWfence", "WWfence");

	__CPROVER_atomic_begin();
	bool old_locked = lock->locked;
	lock->locked = false;
	__CPROVER_atomic_end();

	BUG_ON(!old_locked);
#endif
}

static inline void set_cookie(struct sk_buff *skb, char code) /* <=== set_cookie */ 
{
	((char *)skb->data)[NOTIFY_COOKIE_LEN-1] = code;
}

static inline struct fd __to_fd(unsigned long v) /* <=== __to_fd */ 
{
	return (struct fd){(struct file *)(v & ~3),v & 3};
}

